(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[561],{7561:function(s,a,n){Promise.resolve().then(n.bind(n,9747))},9747:function(s,a,n){"use strict";n.d(a,{default:function(){return o}});var l=n(7437),c=n(2265),e=n(2714);let i='<svg width="0" height="0" style="position:absolute" aria-hidden="true"><defs>\n  <linearGradient id="brandGrad" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#8b7cff"/><stop offset=".5" stop-color="#5ac8ff"/><stop offset="1" stop-color="#ff79c0"/></linearGradient>\n  <symbol id="nodeMark" viewBox="0 0 40 40">\n    <rect x="2" y="2" width="36" height="36" rx="11" fill="url(#brandGrad)"/>\n    <g stroke="#070709" stroke-width="2.6" stroke-linecap="round" fill="none"><line x1="13.5" y1="27" x2="13.5" y2="13"/><line x1="13.5" y1="13" x2="26.5" y2="27"/><line x1="26.5" y1="27" x2="26.5" y2="13"/></g>\n    <g fill="#070709"><circle cx="13.5" cy="13" r="3"/><circle cx="13.5" cy="27" r="3"/><circle cx="26.5" cy="13" r="3"/><circle cx="26.5" cy="27" r="3"/></g>\n  </symbol>\n</defs></svg>\n<div class="grain"></div>\n<div class="cursor" id="cursor"></div>\n<div class="progress" id="progress"></div>\n\n<!-- PRELOADER -->\n<div class="preloader" id="preloader">\n  <div class="ring"></div>\n  <div class="pl-inner">\n    <div class="pl-count" id="plCount">00</div>\n    <div class="pl-label">NODA \xb7 загрузка</div>\n    <div class="pl-bar"><i id="plBar"></i></div>\n  </div>\n</div>\n\n<!-- NAV -->\n<header class="nav" id="nav">\n  <div class="nav-in">\n    <a href="/" class="brand"><svg class="mark" viewBox="0 0 40 40"><use href="#nodeMark"/></svg>NODA</a>\n    <nav class="nav-links"><a href="/">Главная</a><a href="#cases">Кейсы</a><a href="#calc">Калькулятор</a><a href="#contact">Контакты</a></nav>\n    <div class="nav-right"><!--PHONE--><button class="btn btn-primary">Обсудить проект</button></div>\n  </div>\n<!--SUB--></header>\n\n<main>\n  <!-- HERO -->\n  <section class="hero">\n    <canvas id="gl"></canvas>\n    <span class="hero-core"></span>\n    <canvas id="blob"></canvas>\n    <span class="hero-orb x" data-speed="-40"></span><span class="hero-orb y" data-speed="60"></span>\n    <div class="wrap hero-inner">\n      <span class="eyebrow"><span class="dot"></span><span id="scramble">Студия автоматизации и ИИ</span></span>\n      <h1 class="h1 disp">\n        <span class="line"><span style="--i:0">Автоматизация,</span></span>\n        <span class="line"><span style="--i:1">которая окупается</span></span>\n        <span class="line"><span style="--i:2">уже в <span class="accent">первые месяцы</span></span></span>\n      </h1>\n      <p class="lead">Telegram-боты, CRM, сайты и понятная отчётность. Сначала разбираем задачу и показываем работающий прототип — и только потом договариваемся о полной разработке.</p>\n      <div class="cta-row">\n        <button class="btn btn-primary">Обсудить проект →</button>\n        <button class="btn btn-ghost">Смотреть кейсы</button>\n      </div>\n      <div class="promo"><span class="promo-dot"></span>Запуск со скидкой <b>−30%</b> на все услуги \xb7 до 31 июля</div>\n      <div class="trust"><span><b>50+</b> проектов</span><span class="sep"></span><span>запуск за <b>2–4 недели</b></span><span class="sep"></span><span>поддержка <b>24/7</b></span></div>\n    </div>\n    <div class="scroll-hint"><span class="mouse"></span>Листайте</div>\n  </section>\n\n  <!-- VELOCITY MARQUEE -->\n  <section class="marquee"><div class="mq-track" id="mq">\n    <span class="s">Telegram-боты</span><span class="s"><b>Внедрение ИИ</b></span><span class="s">ИИ-агенты</span><span class="s">CRM под ключ</span><span class="s"><b>Веб-приложения</b></span><span class="s">Скрипты и парсинг</span><span class="s">Бизнес-аналитика</span><span class="s"><b>Дашборды</b></span><span class="s">Интеграции</span>\n    <span class="s">Telegram-боты</span><span class="s"><b>Внедрение ИИ</b></span><span class="s">ИИ-агенты</span><span class="s">CRM под ключ</span><span class="s"><b>Веб-приложения</b></span><span class="s">Скрипты и парсинг</span><span class="s">Бизнес-аналитика</span><span class="s"><b>Дашборды</b></span><span class="s">Интеграции</span>\n  </div></section>\n\n  <!-- BENTO SERVICES -->\n  <section class="pad" id="services"><div class="wrap">\n    <div class="shead">\n      <span class="eyebrow" data-reveal>Что мы делаем</span>\n      <h2 class="disp" data-reveal style="--i:1">Пять направлений,<br>одна связка</h2>\n      <p data-reveal style="--i:2">Берите что-то одно или связку целиком: бот собирает заявки, CRM их не теряет, а отчёты показывают, что сработало.</p><div class="svc-hint" data-reveal style="--i:3"><span class="svc-hint-ic">→</span>Нажмите на любую услугу — откроется её страница</div>\n    </div>\n    <div class="bento">\n      <article class="cell b1" data-reveal><a class="cover-link" href="/uslugi/vnedrenie-ii" aria-label="Автоматизация и ИИ — подробнее"></a>\n        <span class="glare"></span><span class="core"></span>\n        <h3>Автоматизация и ИИ</h3>\n        <p>Боты для продаж и поддержки, ИИ-ассистенты, парсинг и скрипты — всё, что забирает у команды ручную работу.</p>\n        <div class="tags"><span class="tag">Telegram-боты</span><span class="tag">ИИ-агенты</span><span class="tag">Интеграция ИИ</span><span class="tag">Скрипты</span></div>\n      <a class="cell-go" href="/uslugi/vnedrenie-ii" tabindex="-1">Перейти к услуге<span class="cell-go-i">→</span></a></article>\n      <article class="cell b2" data-reveal style="--i:1"><a class="cover-link" href="/uslugi/sajty-i-prilozheniya" aria-label="Веб и приложения — подробнее"></a>\n        <span class="glare"></span>\n        <div class="ico"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><rect x="3" y="4" width="18" height="14" rx="2"/><path d="M3 9h18M8 21h8"/></svg></div>\n        <h3>Веб и приложения</h3><p>Лендинги, сайты компаний и личные кабинеты: быстрые, аккуратные, с понятной админкой.</p>\n      <a class="cell-go" href="/uslugi/sajty-i-prilozheniya" tabindex="-1">Перейти к услуге<span class="cell-go-i">→</span></a></article>\n      <article class="cell" data-reveal style="--i:2"><a class="cover-link" href="/uslugi/crm" aria-label="CRM под ключ — подробнее"></a>\n        <span class="glare"></span><h3>CRM под ключ</h3><p>Настроим amoCRM или Битрикс24, а если в коробке тесно — соберём свою.</p>\n      <a class="cell-go" href="/uslugi/crm" tabindex="-1">Перейти к услуге<span class="cell-go-i">→</span></a></article>\n      <article class="cell" data-reveal style="--i:3"><a class="cover-link" href="/uslugi/telegram-boty" aria-label="Скрипты и боты — подробнее"></a>\n        <span class="glare"></span><h3>Скрипты</h3><p>Парсинг сайтов, автозаполнение таблиц, связки между сервисами.</p>\n      <a class="cell-go" href="/uslugi/telegram-boty" tabindex="-1">Перейти к услуге<span class="cell-go-i">→</span></a></article>\n      <article class="cell b5" data-reveal style="--i:2"><a class="cover-link" href="/uslugi/analitika" aria-label="Данные и аналитика — подробнее"></a>\n        <span class="glare"></span><span class="chart"><i></i><i></i><i></i><i></i><i></i></span>\n        <h3>Данные и аналитика</h3><p>Дашборды и отчёты, из которых видно, где теряются деньги.</p>\n      <a class="cell-go" href="/uslugi/analitika" tabindex="-1">Перейти к услуге<span class="cell-go-i">→</span></a></article>\n      <article class="cell b6" data-reveal style="--i:3"><a class="cover-link" href="/uslugi/vnedrenie-ii" aria-label="Интеграция ИИ в системы — подробнее"></a>\n        <span class="glare"></span>\n        <div class="ico"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M12 2v4M12 18v4M2 12h4M18 12h4"/><circle cx="12" cy="12" r="3.2"/></svg></div>\n        <h3>Интеграция ИИ в системы</h3><p>Встраиваем GPT-модели в ваши сервисы: ответы клиентам, разбор документов, черновики текстов.</p>\n      <a class="cell-go" href="/uslugi/vnedrenie-ii" tabindex="-1">Перейти к услуге<span class="cell-go-i">→</span></a></article>\n    </div>\n  </div></section>\n\n  <!-- SHOWCASE (RGB-shift on hover) -->\n  <section class="pad" id="showcase"><div class="wrap">\n    <div class="shead">\n      <span class="eyebrow" data-reveal>Кому это подходит</span>\n      <h2 class="disp" data-reveal style="--i:1">Под вашу нишу<br>уже есть сценарий</h2>\n    </div>\n    <div class="shots">\n      <a class="shot" data-reveal data-cursor="смотреть"><span class="shot-img g1"></span><span class="shot-art"><svg viewBox="0 0 200 200" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><defs><linearGradient id="e1g" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#ffffff"/><stop offset="1" stop-color="#7df0ff"/></linearGradient><radialGradient id="e1n" cx="50%" cy="50%" r="50%"><stop offset="0" stop-color="#ffffff" stop-opacity=".6"/><stop offset="1" stop-color="#ffffff" stop-opacity="0"/></radialGradient></defs><g stroke="#ffffff" stroke-opacity=".2" stroke-width="1"><path d="M20 152 H180"/><path d="M34 170 H166"/><path d="M44 134 L20 170"/><path d="M84 134 L74 170"/><path d="M120 134 L130 170"/><path d="M160 134 L184 170"/></g><g stroke="url(#e1g)" stroke-width="1.8" stroke-linecap="round" opacity=".85"><path d="M46 46 L92 96"/><path d="M100 30 L104 92"/><path d="M154 46 L116 96"/></g><g><circle cx="46" cy="46" r="13" fill="url(#e1n)"/><circle cx="46" cy="46" r="4.4" fill="#fff"/><circle cx="100" cy="30" r="13" fill="url(#e1n)"/><circle cx="100" cy="30" r="4.4" fill="#fff"/><circle cx="154" cy="46" r="13" fill="url(#e1n)"/><circle cx="154" cy="46" r="4.4" fill="#fff"/></g><g stroke="#ffffff" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round" fill="none"><path d="M66 96 H150 L140 134 H84 Z" fill="rgba(8,10,20,.2)"/><path d="M50 86 H66 L84 134"/><path d="M76 114 H146"/></g><circle cx="94" cy="148" r="7" stroke="#ffffff" stroke-width="2.3"/><circle cx="132" cy="148" r="7" stroke="#ffffff" stroke-width="2.3"/></svg></span><span class="shot-meta"><b>E-commerce</b><i>бот + CRM + аналитика</i></span></a>\n      <a class="shot" data-reveal style="--i:1" data-cursor="смотреть"><span class="shot-img g2"></span><span class="shot-art"><svg viewBox="0 0 200 200" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><defs><linearGradient id="f2g" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#ffffff"/><stop offset="1" stop-color="#ff9ed6"/></linearGradient><radialGradient id="f2n" cx="50%" cy="50%" r="50%"><stop offset="0" stop-color="#ffffff" stop-opacity=".7"/><stop offset="1" stop-color="#ffffff" stop-opacity="0"/></radialGradient></defs><g fill="#ffffff"><circle cx="68" cy="32" r="3.2" opacity=".8"/><circle cx="100" cy="24" r="3.8"/><circle cx="132" cy="34" r="3.2" opacity=".8"/><circle cx="84" cy="48" r="2.6" opacity=".55"/><circle cx="118" cy="48" r="2.6" opacity=".55"/></g><g stroke="#ffffff" stroke-width="2.2" fill="none" stroke-linejoin="round"><path d="M44 74 L92 140 V164 L108 164 V140 L156 74Z" fill="rgba(8,10,20,.22)"/><ellipse cx="100" cy="74" rx="56" ry="12"/><ellipse cx="100" cy="74" rx="36" ry="7.5" stroke-opacity=".5"/><path d="M73 102 H127" stroke-opacity=".4"/><path d="M86 122 H114" stroke-opacity=".4"/></g><g fill="url(#f2g)"><circle cx="97" cy="92" r="3"/><circle cx="105" cy="112" r="2.6"/><circle cx="100" cy="132" r="2.6"/></g><circle cx="100" cy="180" r="14" fill="url(#f2n)"/><circle cx="100" cy="180" r="5" fill="#ffffff"/></svg></span><span class="shot-meta"><b>Услуги и эксперты</b><i>воронка в Telegram</i></span></a>\n      <a class="shot" data-reveal style="--i:2" data-cursor="смотреть"><span class="shot-img g3"></span><span class="shot-art"><svg viewBox="0 0 200 200" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><defs><linearGradient id="d3g" x1="0" y1="1" x2="0" y2="0"><stop offset="0" stop-color="#7df0ff" stop-opacity=".5"/><stop offset="1" stop-color="#ffffff"/></linearGradient><radialGradient id="d3n" cx="50%" cy="50%" r="50%"><stop offset="0" stop-color="#ffffff" stop-opacity=".7"/><stop offset="1" stop-color="#ffffff" stop-opacity="0"/></radialGradient></defs><rect x="26" y="40" width="148" height="122" rx="15" fill="rgba(8,10,20,.3)" stroke="#ffffff" stroke-width="2.2"/><line x1="26" y1="63" x2="174" y2="63" stroke="#ffffff" stroke-opacity=".4" stroke-width="1.6"/><g fill="#ffffff" opacity=".7"><circle cx="41" cy="52" r="2.6"/><circle cx="51" cy="52" r="2.6"/><circle cx="61" cy="52" r="2.6"/></g><g stroke="#ffffff" stroke-opacity=".13" stroke-width="1"><line x1="40" y1="94" x2="160" y2="94"/><line x1="40" y1="120" x2="160" y2="120"/><line x1="40" y1="146" x2="160" y2="146"/></g><g fill="url(#d3g)"><rect x="46" y="122" width="13" height="28" rx="2"/><rect x="68" y="106" width="13" height="44" rx="2"/><rect x="90" y="114" width="13" height="36" rx="2"/></g><path d="M46 118 L74 102 L96 108 L150 80" stroke="#ffffff" stroke-width="2.6" fill="none" stroke-linecap="round" stroke-linejoin="round"/><circle cx="150" cy="80" r="11" fill="url(#d3n)"/><circle cx="150" cy="80" r="4.4" fill="#ffffff"/><circle cx="139" cy="130" r="16" stroke="#ffffff" stroke-opacity=".25" stroke-width="4" fill="none"/><path d="M139 114 a16 16 0 0 1 12.5 25.5" stroke="url(#d3g)" stroke-width="4" fill="none" stroke-linecap="round"/></svg></span><span class="shot-meta"><b>Производство</b><i>дашборды и отчётность</i></span></a>\n    </div>\n  </div></section>\n\n  <!-- HORIZONTAL PIN -->\n  <section class="horizontal" id="cases" data-cursor="↔ тянуть">\n    <div class="h-head"><span class="eyebrow">Кейсы и компетенции →</span></div>\n    <div class="h-track" id="htrack">\n      <article class="h-panel"><span class="pglow"></span><div class="num">01</div><div><h3>Telegram-бот для продаж</h3><p>Отвечает за минуту в любое время суток, задаёт три вопроса и передаёт менеджеру уже тёплого клиента.</p></div></article>\n      <article class="h-panel"><span class="pglow"></span><div class="num">02</div><div><h3>ИИ-ассистент в поддержку</h3><p>Закрывает типовые вопросы ночью и в выходные. Человеку достаются только нестандартные случаи.</p></div></article>\n      <article class="h-panel"><span class="pglow"></span><div class="num">03</div><div><h3>CRM под нишу</h3><p>Воронки как в вашем отделе продаж, а не как в шаблоне. Звонки и переписки — в карточке клиента.</p></div></article>\n      <article class="h-panel"><span class="pglow"></span><div class="num">04</div><div><h3>Парсинг и автоматизация</h3><p>Скрипт за ночь собирает то, на что у сотрудника уходила неделя, и утром кладёт отчёт в таблицу.</p></div></article>\n      <article class="h-panel"><span class="pglow"></span><div class="num">05</div><div><h3>Аналитический дашборд</h3><p>Выручка, заявки и реклама на одном экране. Открыли утром — и видно, что происходит.</p></div></article>\n    </div>\n  </section>\n\n  <!-- STATEMENT + CONSTELLATION -->\n  <section class="statement">\n    <canvas id="net"></canvas>\n    <div class="wrap"><h2 class="reveal-words">Нам платят не за строчки кода, а за <span class="accent">освободившиеся часы</span> и заявки, которые перестали теряться.</h2></div>\n  </section>\n\n  <!-- STATS -->\n  <section class="wrap"><div class="stats" data-reveal>\n    <div class="stat"><div class="num" data-count="50" data-suffix="+">0</div><div class="lbl">проектов сдано</div></div>\n    <div class="stat"><div class="num" data-count="9">0</div><div class="lbl">направлений работы</div></div>\n    <div class="stat"><div class="num" data-count="14" data-suffix=" дн">0</div><div class="lbl">средний MVP</div></div>\n    <div class="stat"><div class="num" data-count="24" data-suffix="/7">0</div><div class="lbl">поддержка</div></div>\n  </div></section>\n\n  <!-- PROCESS -->\n  <section class="pad glitch-sec" id="process"><div class="wrap">\n    <div class="shead"><span class="eyebrow" data-reveal>Как мы работаем</span><h2 class="disp glitchy" data-reveal style="--i:1">Три шага от идеи до запуска</h2></div>\n    <div class="steps">\n      <div class="step" data-reveal><h4>Короткий созвон</h4><p>Полчаса: что болит, как устроен процесс, какие цифры. Сразу честно говорим, что стоит автоматизировать, а что — нет.</p><span class="bar"></span></div>\n      <div class="step" data-reveal style="--i:1"><h4>Прототип в руках</h4><p>Через несколько дней вы кликаете по работающему куску продукта, а не смотрите презентацию.</p><span class="bar"></span></div>\n      <div class="step" data-reveal style="--i:2"><h4>Запуск и сопровождение</h4><p>Выкладываем, показываем команде, остаёмся на связи. Правки после запуска — это нормально, мы рядом.</p><span class="bar"></span></div>\n    </div>\n  </div></section>\n\n  <!-- CALCULATOR -->\n  <section class="pad" id="calc"><div class="wrap">\n    <div class="shead">\n      <span class="eyebrow" data-reveal>Калькулятор стоимости</span>\n      <h2 class="disp" data-reveal style="--i:1">Прикиньте бюджет<br>за минуту</h2>\n      <p data-reveal style="--i:2">Выберите услугу и формат — смета пересчитается сразу. <b style="color:var(--ink)">Цены уже с учётом скидки 30%</b>; точную стоимость зафиксируем после короткого брифа.</p>\n    </div>\n    <div class="calc" data-reveal>\n      <div class="calc-controls">\n        <div class="calc-group">\n          <span class="calc-label">Услуга</span>\n          <div class="seg" id="calcService">\n            <button data-svc="bot" class="on">Telegram-бот</button>\n            <button data-svc="ai">Внедрение ИИ</button>\n            <button data-svc="web">Сайт / приложение</button>\n            <button data-svc="crm">CRM</button>\n            <button data-svc="data">Аналитика</button>\n          </div>\n        </div>\n        <div class="calc-group">\n          <span class="calc-label">Формат</span>\n          <div class="seg" id="calcCx">\n            <button data-p="20000" data-t="3–7 дней" data-hint="Кнопки, ответы на частые вопросы, заявки к вам в чат или в таблицу.">Простой бот: меню и заявки</button>\n            <button data-p="50000" data-t="1–2 недели" class="on" data-hint="Каталог или запись, приём оплаты, заявки в CRM, напоминания клиентам.">Бот для продаж</button>\n            <button data-p="100000" data-t="2–3 недели" data-hint="Отвечает свободным текстом по вашей базе знаний, сложное передаёт менеджеру.">Бот с ИИ-ответами</button>\n          </div>\n          <span class="calc-hint" id="cxHint">Каталог или запись, приём оплаты, заявки в CRM, напоминания клиентам.</span>\n        </div>\n        <div class="calc-group">\n          <span class="calc-label">Дополнительно</span>\n          <div class="opts" id="calcOpts">\n            <label class="opt"><input type="checkbox" data-price="12000" data-name="Приём платежей (ЮKassa/Telegram Pay)"><span>Приём платежей (ЮKassa/Telegram Pay)</span><i>+12 000 ₽</i></label>\n            <label class="opt"><input type="checkbox" data-price="15000" data-name="Интеграция с CRM"><span>Интеграция с CRM</span><i>+15 000 ₽</i></label>\n            <label class="opt"><input type="checkbox" data-price="20000" data-name="Рассылки и админ-панель"><span>Рассылки и админ-панель</span><i>+20 000 ₽</i></label>\n            <label class="opt"><input type="checkbox" data-price="60000" data-name="Telegram Mini App"><span>Telegram Mini App</span><i>+60 000 ₽</i></label>\n            <label class="opt"><input type="checkbox" data-price="15000" data-name="Подписки и платный доступ"><span>Подписки и платный доступ</span><i>+15 000 ₽</i></label>\n            <label class="opt"><input type="checkbox" data-price="18000" data-name="Парсинг и автозаполнение данных"><span>Парсинг и автозаполнение данных</span><i>+18 000 ₽</i></label>\n          </div>\n        </div>\n        <div class="calc-group calc-row">\n          <span class="calc-label" style="margin:0">Срочный запуск <small>(\xd71.3 к сроку и цене)</small></span>\n          <button class="switch" id="calcUrgent" role="switch" aria-checked="false" aria-label="Срочный запуск"><span></span></button>\n        </div>\n      </div>\n      <aside class="calc-summary">\n        <div class="cs-head">\n          <div class="cs-caprow"><span class="cs-cap">Стоимость со скидкой</span><span class="cs-badge">−30%</span></div>\n          <s class="cs-old" id="csOld">0 – 0 ₽</s>\n          <div class="cs-amount"><span id="csMin">0</span> – <span id="csMax">0</span> <b>₽</b></div>\n          <div class="cs-svc" id="csSvc">Telegram / чат-бот \xb7 Бот для продаж</div>\n        </div>\n        <ul class="cs-list" id="csList"></ul>\n        <div class="cs-term">Ориентировочный срок: <b id="csTerm">1–2 недели</b></div>\n        <button class="btn btn-primary" style="width:100%;justify-content:center">Получить точную смету →</button>\n        <p class="cs-note">Предварительный расчёт. Точную цену зафиксируем после короткого брифа.</p>\n      </aside>\n    </div>\n  </div></section>\n\n  <!-- FINAL -->\n  <section class="wrap" id="contact"><div class="final" data-reveal>\n    <span class="orb a"></span><span class="orb b"></span>\n    <h2 class="disp">Давайте посчитаем вашу задачу</h2>\n    <p>Напишите пару предложений о том, что хотите автоматизировать, — вернёмся с планом и вилкой цены. Бесплатно.</p>\n    <div class="cta-row"><button class="btn btn-primary">Написать в Telegram</button><button class="btn btn-ghost">Оставить заявку</button></div><!--CONTACTS-->\n  </div></section>\n</main>\n\n<footer><div class="wrap foot">\n  <a href="/" class="brand"><svg class="mark" viewBox="0 0 40 40"><use href="#nodeMark"/></svg>NODA</a>\n  <div class="foot-links"><a href="#services">Услуги</a><a href="#cases">Кейсы</a><a href="#contact">Контакты</a><!--FOOT--></div>\n  <span>\xa9 2026 NODA. Автоматизация и ИИ.</span>\n</div></footer>\n\n<nav class="dock">\n  <a href="/" class="active"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M3 10.5 12 3l9 7.5"/><path d="M5 9.5V21h14V9.5"/></svg>Главная</a>\n  <a href="#services"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/></svg>Услуги</a>\n  <a href="#contact" class="cta"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M22 2 11 13M22 2l-7 20-4-9-9-4 20-7z"/></svg>Написать</a>\n  <a href="#calc"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><rect x="5" y="3" width="14" height="18" rx="2"/><path d="M8 7h8M8 11h2M14 11h2M8 15h2M14 15h2"/></svg>Расчёт</a>\n  <a href="#contact"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><circle cx="12" cy="8" r="4"/><path d="M4 21c0-4 3.5-6 8-6s8 2 8 6"/></svg>Контакты</a>\n</nav>'.replace("<!--SUB-->",()=>(0,e.w6)("ru")).replace("<!--CONTACTS-->",()=>(0,e.U6)()).replace("<!--FOOT-->",()=>(0,e.pp)("ru")).replace("<!--PHONE-->",()=>(0,e.tb)("ru"));var t=n(1275),r=n(5652),p=n(3316);let d=n(257).env.NEXT_PUBLIC_BASE_PATH||"";function o(s){let a,{lang:n="ru"}=s;return(0,c.useEffect)(()=>{(0,p.n)(n).catch(s=>console.error("initSite failed",s))},[n]),(0,l.jsx)("div",{suppressHydrationWarning:!0,dangerouslySetInnerHTML:{__html:(a=(0,r.Hx)(i,n)+(0,t.c)(n),"en"===n&&(a=a.replaceAll('href="/','href="/en/')),d&&(a=a.replaceAll('href="/','href="'.concat(d,"/"))),a)}})}}}]);